            count += 1
            i += 2
        else if i > 0 and i+1 < length(array) and array[i-1] == array[i] and array[i] != array[i+1]:
            count += 1
            i += 2
        else if i == length(array) - 1 and array[i-1] == array[i]:
            count += 1
            break
        else:
            i += 1

    return count

