function evaluateExpression(expression):
    tokens = tokenize(expression)
    stack_num = new stack()
    stack_op = new stack()
    for each token in tokens:
        if token is a number:
            push token to stack_num
        else if token is an operator:
            while stack_op is not empty and top of stack_op has higher or equal precedence:
                op = pop stack_op
                v2 = pop stack_num
                v1 = pop stack_num
                push calculate(op, v1, v2) to stack_num
            push token to stack_op
        else if token is '(':
            push token to stack_op
        else if token is ')':
            while top of stack_op is not '(':
                op = pop stack_op
                v2 = pop stack_num
                v1 = pop stack_num
                push calculate(op, v1, v2) to stack_num
            pop '(' from stack_op
    while stack_op is not empty:
        op = pop stack_op
        v2 = pop stack_num
        v1 = pop stack_num
        push calculate(op, v1, v2) to stack_num
    return top of stack_num

