function countOnePaths(N, M, edges):
    joint = new boolean[N, N]
    for each edge in edges:
        joint[edge.a, edge.b] = true
        joint[edge.b, edge.a] = true

    dp = new int[2^N, N]
    for i from 0 to N-1:
        dp[1 << i, i] = 1

    for bit from 1 to 2^N-1:
        for last from 0 to N-1:
            if (bit & (1 << last)) == 0: continue
            for prev from 0 to N-1:
                if ((bit - (1 << last)) & (1 << prev)) > 0:
                    if joint[last, prev]:
                        dp[bit, last] += dp[bit - (1 << last), prev]

    return dp[2^N-1, 0]
